import {getClient,imageURL,functionURL} from './client.js';
import {checkStaff,imageFor} from './data.js';
import {adminSnapshot,rpc,listEnquiries,changeLog} from './admin-data.js';
import {escapeHtml as e,slugify,productPrice,availability,normalizeBrand,descendants,safeImageUrl} from './model.js';
import {validateFiles,prepareImage,uploadPrepared,retainedImageNotice} from './media.js';
import {PRODUCT_BUCKET,MEDIA_BUCKET,MAX_IMAGES,LOCAL_PREVIEW} from './config.js';
import {$,toast,messageBox,initImages} from './ui.js';
import {icon} from './icons.js';
initImages();
let db,profile,editor=null,tab='products',selected=new Set(),productPage=1,currentCatalog='',enquiryPage=1,enquiryRows=[];
let productFilters={q:'',category:'',type:'',publication:'',review:''};let enquiriesFilter={status:'',reference:''};let adminSequence=0;
const DISABLED=()=>db?.legacy||LOCAL_PREVIEW?'disabled':'';
const date=v=>v?new Date(v).toLocaleString():'Not recorded';
const button=(text,attrs='',primary=false)=>`<button type="button" class="btn ${primary?'btn-primary':'btn-small'}" ${attrs}>${text}</button>`;
const field=(label,name,value='',attrs='')=>`<label class="field"><span>${label}</span><input name="${name}" value="${e(value)}" ${attrs}></label>`;
const option=(value,label,current)=>`<option value="${e(value)}" ${String(current??'')===String(value)?'selected':''}>${e(label)}</option>`;
const selectField=(label,name,value,options)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,l])=>option(v,l,value)).join('')}</select></label>`;
const check=(label,name,checked=false,extra='')=>`<label class="field-check"><input type="checkbox" name="${name}" ${checked?'checked':''} ${extra}><span>${label}</span></label>`;
const activeCategoryNames=p=>(p.category_ids||[]).map(id=>db.categories.find(c=>c.id===id)?.name).filter(Boolean).join(', ');
function showMessage(text,type='success'){const n=$('#adminMessage');n.hidden=!text;n.innerHTML=text?messageBox(text,type):'';}
async function refreshData(){db=await adminSnapshot();return db;}
function renderStats(){return `<div class="admin-stats"><div class="stat"><strong>${db.products.length}</strong><span>Total products</span></div><div class="stat"><strong>${db.products.filter(p=>p.is_published&&p.status!=='hidden').length}</strong><span>Public listings</span></div><div class="stat"><strong>${db.products.filter(p=>availability(p).key==='confirm').length}</strong><span>Stock needs confirmation</span></div><div class="stat"><strong>${db.categories.length}</strong><span>Equipment categories</span></div></div>`;}
function heading(title,description,actions=''){return `<div class="admin-page-heading"><div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="actions">${actions}</div></div>`;}
function setTab(next){
 clearTimeout(searchTimer);
 if(settingsDirty&&next!=='settings'&&!confirm('Discard unsaved site settings?'))return;
 if(next!=='settings')settingsDirty=false;
 if(!['products','organization','media','enquiries','history','settings'].includes(next))next='products';
 tab=next;adminSequence++;selected.clear();document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));history.replaceState({},'',`admin.html?tab=${tab}`);showMessage('');renderTab();
}
async function renderTab(){
 if(!db)return;
 if(tab==='products')renderProductView();
 if(tab==='organization')renderOrganization();
 if(tab==='media')renderMedia();
 if(tab==='settings')renderSettings();
 if(tab==='enquiries')await renderEnquiries();
 if(tab==='history')await renderHistory();
}
function renderProductView(){
 $('#adminContent').innerHTML=heading('Products','Manage each item once, then place it in one or more categories.',button('Export inventory','data-export-inventory')+button(`${icon('plus')} Add Product`, `data-new-product ${DISABLED()}`,true))+renderStats()+`<div class="admin-toolbar"><input type="search" id="adminSearch" placeholder="Search name, model, SKU…" aria-label="Search products" value="${e(productFilters.q)}"><select id="adminCategory" aria-label="Category">${option('','All categories',productFilters.category)}${db.categories.map(c=>option(c.id,c.name,productFilters.category)).join('')}</select><select id="adminType" aria-label="Listing type">${[['','All types'],['product','Sale'],['rental','Rental'],['both','Sale + Rental']].map(x=>option(...x,productFilters.type)).join('')}</select><select id="adminPublication" aria-label="Publication">${[['','All visibility'],['published','Published'],['draft','Draft / hidden']].map(x=>option(...x,productFilters.publication)).join('')}</select><select id="adminReview" aria-label="Needs review">${[['','All availability'],['confirm','Stock needs confirmation'],['uncategorized','Uncategorized']].map(x=>option(...x,productFilters.review)).join('')}</select>${button('Refresh','data-refresh')}</div><div id="bulkBar" hidden></div><div id="productTable"></div><nav class="pagination" id="adminPagination" aria-label="Inventory pages"></nav>`;
 renderProductRows();
}
function filteredProducts(){return db.products.filter(p=>{
 const query=productFilters.q.toLowerCase().trim();return (!query||[p.name,p.brand,p.model,p.sku,activeCategoryNames(p)].filter(Boolean).join(' ').toLowerCase().includes(query))&&(!productFilters.category||p.category_ids.includes(productFilters.category))&&(!productFilters.type||p.listing_type===productFilters.type)&&(!productFilters.publication||(productFilters.publication==='published'?(p.is_published&&p.status!=='hidden'):(!p.is_published||p.status==='hidden')))&&(!productFilters.review||(productFilters.review==='confirm'?availability(p).key==='confirm':!p.category_ids.length));
});}
function renderProductRows(){
 if(tab!=='products'||!$('#productTable'))return;
 const filtered=filteredProducts(),pages=Math.max(1,Math.ceil(filtered.length/40));productPage=Math.min(productPage,pages);const rows=filtered.slice((productPage-1)*40,productPage*40);
 $('#productTable').innerHTML=rows.length?`<div class="table-wrap"><table class="inventory-table"><thead><tr><th><input type="checkbox" id="selectPage" aria-label="Select this page" ${rows.every(p=>selected.has(p.id))?'checked':''} ${DISABLED()}></th><th>Product</th><th>Categories</th><th>Pricing</th><th>Visibility / stock</th><th>Actions</th></tr></thead><tbody>${rows.map(p=>`<tr><td><input type="checkbox" data-select-product="${p.id}" aria-label="Select ${e(p.name)}" ${selected.has(p.id)?'checked':''} ${DISABLED()}></td><td><div class="product-cell"><img src="${e(safeImageUrl(imageFor(p)))}" alt="" width="57" height="57" loading="lazy"><div><strong>${e(p.name)}</strong><small>${e([p.brand,p.model,p.sku?'SKU '+p.sku:''].filter(Boolean).join(' · '))}</small><small>${p.listing_type==='both'?'Sale + Rental':p.listing_type==='rental'?'Rental':'Sale'}</small></div></div></td><td><span class="small">${e(activeCategoryNames(p)||'Uncategorized')}</span></td><td><strong>${e(productPrice(p,p.listing_type==='rental'?'rental':'sale'))}</strong></td><td><span class="pill ${p.is_published&&p.status!=='hidden'?'active':'warning'}">${p.is_published&&p.status!=='hidden'?'Published':'Draft / hidden'}</span><div class="small muted" style="margin-top:7px">${e(availability(p).label)}</div></td><td>${button('Edit',`data-edit-product="${p.id}" ${DISABLED()}`)} <a class="btn btn-small" href="preview.html?id=${p.id}${p.listing_type==='rental'?'&mode=rental':''}" target="_blank" rel="noopener">Preview</a></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h2>No matching products</h2><p>Adjust the filters or create a new product.</p></div>';
 $('#adminPagination').innerHTML=`${button('Previous',`data-admin-page="${productPage-1}" ${productPage===1?'disabled':''}`)}<span class="small">${filtered.length} products · Page ${productPage} of ${pages}</span>${button('Next',`data-admin-page="${productPage+1}" ${productPage>=pages?'disabled':''}`)}`;
 renderBulkBar();
}
function renderBulkBar(){const bar=$('#bulkBar');bar.hidden=!selected.size;bar.innerHTML=selected.size?`<div class="bulk-actions"><span>${selected.size} selected</span>${button('Publish','data-bulk="publish"')}${button('Unpublish','data-bulk="unpublish"')}<select id="bulkCategory" aria-label="Category for selected products"><option value="">Choose category…</option>${db.categories.map(c=>option(c.id,c.name,'')).join('')}</select>${button('Add category','data-bulk="add"')}${button('Remove category','data-bulk="remove"')}</div>`:'';}
async function bulkAction(action,b){
 const ids=[...selected];if(ids.length>200){toast('Select no more than 200 products per bulk change.');return;}
 const cat=$('#bulkCategory')?.value;if(['add','remove'].includes(action)&&!cat){toast('Choose a category first.');return;}
 if(!confirm(`${action==='publish'?'Publish':action==='unpublish'?'Unpublish':action==='add'?'Add category to':'Remove category from'} ${ids.length} selected products?`))return;
 b.disabled=true;const expected=Object.fromEntries(ids.map(id=>[id,db.products.find(p=>p.id===id)?.updated_at]));
 try{
 if(['publish','unpublish'].includes(action))await rpc('bills_set_product_visibility',{p_ids:ids,p_published:action==='publish',p_expected:expected});
 else await rpc('bills_bulk_categories',{p_ids:ids,p_category_id:cat,p_action:action,p_expected:expected});
 selected.clear();await refreshData();renderProductRows();showMessage('Selected products updated.');
 }catch(err){showMessage(err.message,'error');}finally{b.disabled=false;}
}
function imageForCategory(c){if(c.image_path)return imageURL(MEDIA_BUCKET,c.image_path);const ids=descendants(db.categories,c.id);const p=db.products.find(p=>p.category_ids.some(id=>ids.has(id))&&p.product_images.length);return p?imageFor(p):'assets/equipment-placeholder.svg';}
function renderOrganization(){
 if(db.legacy){$('#adminContent').innerHTML=heading('Catalog Organization','The database upgrade enables editable catalogs and category assignments.')+messageBox('Editing is disabled until the included database migration has been reviewed and applied. Existing products have not been moved.','warning');return;}
 const selectedCatalog=db.catalogs.find(c=>c.id===currentCatalog||c.slug===currentCatalog)||db.catalogs.find(c=>c.slug==='equipment')||db.catalogs[0];currentCatalog=selectedCatalog?.id||'';
 const cats=(selectedCatalog?.category_ids||[]).map(id=>db.categories.find(c=>c.id===id)).filter(Boolean);
 $('#adminContent').innerHTML=heading('Catalog Organization','Control the top navigation and the category-image cards customers see.',button(`${icon('plus')} New Catalog`,'data-new-catalog',true))+`<div class="org-layout"><aside class="catalog-tree"><h2>Top navigation order</h2>${db.catalogs.map((c,index)=>`<div class="catalog-row ${c.id===currentCatalog?'active':''}"><button class="catalog-select" data-select-catalog="${c.id}">${e(c.name)}${c.active?'':'<span class="pill">Hidden</span>'}</button><div class="order-controls"><button class="order-btn" data-catalog-order="${c.id}" data-direction="-1" ${index===0?'disabled':''} aria-label="Move ${e(c.name)} up">↑</button><button class="order-btn" data-catalog-order="${c.id}" data-direction="1" ${index===db.catalogs.length-1?'disabled':''} aria-label="Move ${e(c.name)} down">↓</button></div></div>`).join('')}${button('All categories','data-all-categories')}</aside><section class="org-content"><div class="org-content-head"><div><h2>${e(selectedCatalog?.name||'Catalog')}</h2><p class="small muted" style="margin-top:7px">${cats.length} categories · ${selectedCatalog?.active?'Visible in navigation':'Hidden from customers'}</p></div>${button('Edit catalog & order',`data-edit-catalog="${currentCatalog}"`)}</div><div class="category-grid">${cats.map(c=>`<article class="admin-category-card"><h3>${e(c.name)} ${c.active?'':'<span class="pill">Hidden</span>'}</h3><img src="${e(safeImageUrl(imageForCategory(c)))}" alt="${e(c.name)}" loading="lazy"><small class="muted">${db.products.filter(p=>p.category_ids.includes(c.id)).length} direct product assignments</small><div class="actions">${button('Edit',`data-edit-category="${c.id}"`)}${button('Products',`data-category-products="${c.id}"`)}</div></article>`).join('')}<button type="button" class="admin-add-tile" data-new-category>${icon('plus')} Add Category <small>To this catalog</small></button></div></section></div>`;
}
function renderMedia(){
 const files=db.products.flatMap(p=>p.product_images.map(i=>({p,i})));
 $('#adminContent').innerHTML=heading('Media Library','Actual product photos. Edit a product to upload, reorder, set its primary photo or remove a reference.')+`<p class="notice" style="margin-bottom:20px">Product photos and category images are public website assets. Do not upload customer documents or confidential information here. Unreferenced uploads are not deleted automatically.</p><div class="media-grid">${files.map(({p,i})=>`<article class="media-card"><img src="${e(safeImageUrl(imageURL(PRODUCT_BUCKET,i.storage_path)))}" alt="${e(i.alt_text||p.name)}" loading="lazy"><h3>${e(p.name)}</h3><small class="muted">${i.is_primary?'Primary photo':'Gallery photo'}</small>${button('Manage photos',`data-edit-product="${p.id}" ${DISABLED()}`)}</article>`).join('')||'<div class="empty">No product photos are attached yet.</div>'}</div>`;
}
function editorOpen(kind,title,record){
 if(editor&&!editorClose())return;
 if(db.legacy||LOCAL_PREVIEW){toast(LOCAL_PREVIEW?'Local preview is read-only.':'Apply the database upgrade before editing.');return;}
 editor={kind,record:record?structuredClone(record):null,id:record?.id||crypto.randomUUID(),dirty:false,busy:false,images:[],pendingOp:null,objectURLs:[],staged:[],attempted:false};
 $('#editorTitle').textContent=title;$('#editorContent').innerHTML='';$('#editorDialog').showModal();return editor;
}
function editorClose(force=false){
 if(!editor)return true;if(editor.busy)return false;
 if(editor.dirty&&!force&&!confirm('Discard your unsaved changes? Files already staged after a failed save may remain in storage for review.'))return false;
 for(const u of editor.objectURLs)URL.revokeObjectURL(u);editor=null;$('#editorDialog').close();return true;
}
function editorFooter(label='Save changes'){return `<div class="editor-message" id="editorMessage" role="status"></div><div class="editor-footer"><span class="save-note">Changes are saved only when you submit this form.</span><div class="actions">${button('Cancel','data-cancel-editor')}<button class="btn btn-primary" type="submit" id="saveEditor">${label}</button></div></div>`;}
function editorError(text){$('#editorMessage').innerHTML=messageBox(text);$('#editorMessage').scrollIntoView({block:'nearest'});}
function busy(on){if(!editor)return;editor.busy=on;$('#closeEditor').disabled=on;const fs=$('#editorFields');if(fs)fs.disabled=on;$('#saveEditor').disabled=on;$('#saveEditor').textContent=on?'Saving…':'Save changes';$('#editorDialog').setAttribute('aria-busy',String(on));}
async function saved(text,extra=''){
 editor.dirty=false;editor.busy=false;editorClose(true);
 try{await refreshData();await renderTab();showMessage(text+(extra?' '+extra:''),extra?'warning':'success');}catch(err){showMessage(text+' The save was confirmed, but the refreshed list could not load. Click Refresh. '+err.message,'warning');}
}
function productEditor(p=null){
 const ed=editorOpen('product',p?'Edit Product':'Add Product',p);if(!ed)return;
 const v=p||{listing_type:'product',condition:'unspecified',quantity:0,status:'active',call_for_price:true,is_published:false,featured:false,display_order:0,category_ids:[],website:{purchase_mode:'quote',availability:'confirm',rental_call_for_price:true}},s=v.website||{};
 ed.images=(p?.product_images||[]).map(i=>({...i}));
 $('#editorContent').innerHTML=`<form class="editor-form" id="productEditor"><fieldset id="editorFields"><div class="editor-layout"><section class="editor-section"><h3>Equipment details</h3>${field('Product name *','name',v.name,'required maxlength="200"')}${selectField('Listing type','listing_type',v.listing_type,[['product','Sale / equipment'],['rental','Rental'],['both','Sale + Rental']])}<div class="field-row">${field('Brand','brand',v.brand,'maxlength="100" list="knownBrands"')}${field('Model','model',v.model,'maxlength="120"')}</div><datalist id="knownBrands">${[...new Set(db.products.map(x=>x.brand).filter(Boolean))].map(b=>`<option value="${e(b)}">`).join('')}</datalist><div class="field-row">${field('SKU / part number','sku',v.sku,'maxlength="120"')}${selectField('Condition','condition',v.condition,[['unspecified','Not specified'],['new','New'],['used','Used'],['refurbished','Refurbished']])}</div><label class="field"><span>Description</span><textarea name="description" rows="6" maxlength="30000">${e(v.description)}</textarea></label><label class="field"><span>Specifications</span><textarea name="specifications" rows="4" maxlength="20000" placeholder="One specification per line">${e(s.specifications)}</textarea></label><h3>Sale pricing & customer action</h3>${check('Call for Price / quote required','call_for_price',v.call_for_price)}${field('Sale price (USD)','price',v.price??'','type="number" min="0" max="999999999" step="0.01"')}${selectField('Customer action','purchase_mode',s.purchase_mode||'quote',[['quote','Add to quote request'],['information','Information only — contact Bill’s']])}<p class="small muted">A displayed price does not enable online checkout. No payments are taken.</p><h3>Rental pricing</h3>${check('Request rental rate — do not show a daily/weekly/monthly price','rental_call_for_price',s.rental_call_for_price!==false)}<div class="field-row">${field('Daily rate (USD)','rental_day',s.rental_day??'','type="number" min="0.01" step="0.01"')}${field('Weekly rate (USD)','rental_week',s.rental_week??'','type="number" min="0.01" step="0.01"')}</div>${field('Monthly rate (USD)','rental_month',s.rental_month??'','type="number" min="0.01" step="0.01"')}<p class="small muted">Rates are independent of the sale price. Requested dates are not automatic reservations.</p></section><section class="editor-section"><h3>Where this product appears</h3><div class="category-picker" id="productCategoryPicker">${db.categories.map(c=>check(e(c.name)+(c.active?'':' <span class="pill">Hidden</span>'),'category',v.category_ids.includes(c.id),`value="${c.id}"`)).join('')||'<p class="small">Create a category in Catalog Organization first.</p>'}</div><label class="field"><span>Primary category</span><select name="primary_category" id="primaryCategory"></select></label><div class="selected-placement" id="placementSummary"></div><h3>Visibility & stock</h3>${check('Published — visible to customers','is_published',v.is_published)}${check('Featured equipment','featured',v.featured)}<div class="field-row">${selectField('Status','status',v.status,[['active','Active listing'],['out_of_stock','Out of stock'],['sold','Sold'],['hidden','Hidden']])}${field('Display order','display_order',v.display_order,'type="number" min="0" max="1000000" step="1" required')}</div><div class="field-row">${field('Stock quantity','quantity',v.quantity,'type="number" min="0" max="1000000" step="1" required')}${selectField('Availability label','availability',s.availability||'confirm',[['confirm','Confirm availability'],['in_stock','Stock confirmed'],['unavailable','Currently unavailable'],['backorder','Ask about lead time']])}</div>${check('I have checked the physical stock now','verify_stock_now',false)}<small class="muted">Last checked: ${e(date(s.stock_verified_at))}. Stock confirmation expires after 30 days. Imported quantities are not verified stock.</small><h3>Product photos</h3><div id="imageEditList" class="image-edit-list"></div><label class="field"><span>Add photos</span><input type="file" id="addProductImages" accept="image/jpeg,image/png,image/webp,image/avif" multiple><small>Up to 12 photos, 10 MB each. Images are optimized before upload. The first image is the primary photo.</small></label><p id="imageWorkStatus" class="small muted"></p><p class="small muted">Source: ${e(p?.source||'manual')} ${p?.external_id?' · External ID: '+e(p.external_id):''}<br>Product ID: ${ed.id}</p>${p?`<a class="red-link small" href="preview.html?id=${p.id}${p.listing_type==='rental'?'&mode=rental':''}" target="_blank" rel="noopener">Preview the saved product ${icon('arrow')}</a>`:'<p class="small muted">Save as a draft first to preview before publishing.</p>'}</section></div></fieldset>${editorFooter(p?'Save Product':'Save Product')}</form>`;
 renderEditorImages();updatePlacements(v.category_id||v.category_ids[0]||'');updatePriceDisabled();
}
function updatePriceDisabled(){const form=$('#productEditor');if(!form)return;form.elements.price.disabled=form.elements.call_for_price.checked;for(const k of ['rental_day','rental_week','rental_month'])form.elements[k].disabled=form.elements.rental_call_for_price.checked;}
function updatePlacements(primary){const form=$('#productEditor');if(!form)return;const ids=[...form.querySelectorAll('[name=category]:checked')].map(c=>c.value);const current=primary??form.primary_category.value;form.primary_category.innerHTML=ids.length?ids.map(id=>option(id,db.categories.find(c=>c.id===id)?.name||id,current)).join(''):'<option value="">Uncategorized</option>';if(ids.includes(current))form.primary_category.value=current;const names=db.catalogs.filter(cat=>cat.category_ids.some(id=>ids.some(x=>descendants(db.categories,id).has(x)))).map(c=>c.name);$('#placementSummary').textContent=ids.length?`Appears in: ${names.join(', ')||'No catalog assigned to these categories yet.'}`:'Select one or more categories. New products remain drafts until published.';}
function renderEditorImages(){if(!editor||editor.kind!=='product')return;$('#imageEditList').innerHTML=editor.images.map((i,index)=>`<div class="image-edit-row"><img src="${e(i.preview||safeImageUrl(imageURL(PRODUCT_BUCKET,i.storage_path)))}" alt="${e(i.alt_text||'Product photo')}" width="67" height="67"><div><small>${index===0?'Primary photo':`Photo ${index+1}`}${i.blob?' · New':''}</small><input data-image-alt="${i.id}" aria-label="Alternative text for photo ${index+1}" value="${e(i.alt_text||'')}" maxlength="250"></div><div class="actions"><button type="button" data-image-move="${i.id}" data-direction="-1" ${index===0?'disabled':''} aria-label="Move photo up">↑</button><button type="button" data-image-move="${i.id}" data-direction="1" ${index===editor.images.length-1?'disabled':''} aria-label="Move photo down">↓</button><button type="button" data-image-remove="${i.id}" aria-label="Remove photo">×</button></div></div>`).join('')||'<p class="notice">No photos selected. Customers will see a placeholder until you add a photo.</p>';}
async function addProductFiles(input){
 const ed=editor,files=[...input.files];if(!files.length)return;
 try{
 validateFiles(files,ed.images.length);ed.busy=true;$('#saveEditor').disabled=true;$('#imageWorkStatus').textContent='Preparing images…';
 // All files must decode successfully before any are added or uploaded.
 const prepared=[];for(const file of files)prepared.push(await prepareImage(file));
 if(editor!==ed)return;
 for(let index=0;index<prepared.length;index++){const id=crypto.randomUUID(),blob=prepared[index],url=URL.createObjectURL(blob);ed.objectURLs.push(url);ed.images.push({id,storage_path:`${ed.id}/${id}.webp`,alt_text:$('#productEditor').elements.name.value||files[index].name,blob,preview:url,uploaded:false});}
 ed.dirty=true;renderEditorImages();$('#imageWorkStatus').textContent='Photos prepared. They will be uploaded when you save.';
 }catch(err){editorError(err.message);$('#imageWorkStatus').textContent='No new photos were added.';}finally{if(editor===ed){ed.busy=false;$('#saveEditor').disabled=false;input.value='';}}
}
async function saveProduct(form){
 const ed=editor;if(ed.busy)return;if(!form.reportValidity())return;
 const f=Object.fromEntries(new FormData(form));const categories=[...form.querySelectorAll('[name=category]:checked')].map(c=>c.value);const ordered=f.primary_category?[f.primary_category,...categories.filter(id=>id!==f.primary_category)]:categories;
 const product={id:ed.id,name:f.name.trim(),slug:ed.record?.slug||`${slugify(f.name)||'equipment'}-${ed.id.slice(0,8)}`,description:f.description||'',brand:normalizeBrand(f.brand),model:f.model.trim(),sku:f.sku.trim(),listing_type:f.listing_type,condition:f.condition,price:f.call_for_price?null:Number(f.price),call_for_price:!!f.call_for_price,quantity:Number(f.quantity),status:f.status,is_published:!!f.is_published,featured:!!f.featured,display_order:Number(f.display_order)};
 if(!f.call_for_price&&(f.price===''||!Number.isFinite(product.price))){editorError('Enter the sale price or choose Call for Price.');return;}
 if(product.is_published&&!ordered.length){editorError('Assign at least one category before publishing.');return;}
 const settings={purchase_mode:f.purchase_mode,online_purchase_eligible:ed.record?.website?.online_purchase_eligible||false,availability:f.availability,verify_stock_now:!!f.verify_stock_now,rental_call_for_price:!!f.rental_call_for_price,rental_day:f.rental_day||null,rental_week:f.rental_week||null,rental_month:f.rental_month||null,specifications:f.specifications||''};
 if(settings.rental_call_for_price)for(const key of ['rental_day','rental_week','rental_month'])settings[key]=ed.record?.website?.[key]??null;
 const args={p_product:product,p_settings:settings,p_category_ids:ordered,p_images:ed.images.map(i=>({id:i.id,storage_path:i.storage_path,alt_text:i.alt_text||product.name})),p_expected_updated_at:ed.record?.updated_at||null};
 const signature=JSON.stringify(args);if(ed.pendingOp?.signature!==signature)ed.pendingOp={signature,id:crypto.randomUUID()};args.p_operation_id=ed.pendingOp.id;
 busy(true);$('#editorMessage').textContent='';
 try{
 for(const i of ed.images){if(i.blob&&!i.uploaded){$('#imageWorkStatus').textContent='Uploading photos…';await uploadPrepared(PRODUCT_BUCKET,i.storage_path,i.blob);i.uploaded=true;ed.staged.push(i.storage_path);}}
 ed.attempted=true;const result=await rpc('bills_save_product',args);const warning=retainedImageNotice(result.removed_paths);await saved('Product saved.',warning);
 }catch(err){editorError((ed.attempted?'The save could not be confirmed. Your form and product ID were kept; retrying unchanged details will not create a duplicate. ':'')+err.message);}finally{if(editor===ed){busy(false);updatePriceDisabled();}}
}
