// Event delegation keeps editing responsive as tables and dialogs are refreshed.
document.addEventListener('click',async event=>{
 const b=event.target.closest('button');if(!b||b.disabled)return;
 if(b.matches('[data-tab]')){if(settingsDirty&&!confirm('Discard unsaved site settings?'))return;settingsDirty=false;setTab(b.dataset.tab);}
 if(b.matches('[data-refresh]')){try{await refreshData();await renderTab();showMessage('Inventory refreshed.');}catch(err){showMessage(err.message,'error');}}
 if(b.matches('[data-new-product]'))productEditor();
 if(b.dataset.editProduct)productEditor(db.products.find(p=>p.id===b.dataset.editProduct));
 if(b.dataset.adminPage){productPage=Number(b.dataset.adminPage);renderProductRows();}
 if(b.dataset.bulk)await bulkAction(b.dataset.bulk,b);
 if(b.dataset.selectCatalog){currentCatalog=b.dataset.selectCatalog;renderOrganization();}
 if(b.matches('[data-new-catalog]'))catalogEditor();
 if(b.dataset.editCatalog)catalogEditor(db.catalogs.find(c=>c.id===b.dataset.editCatalog));
 if(b.matches('[data-new-category]'))categoryEditor();
 if(b.dataset.editCategory)categoryEditor(db.categories.find(c=>c.id===b.dataset.editCategory));
 if(b.dataset.categoryProducts){productFilters.category=b.dataset.categoryProducts;productPage=1;setTab('products');}
 if(b.dataset.catalogOrder)await reorderCatalog(b.dataset.catalogOrder,Number(b.dataset.direction));
 if(b.matches('[data-all-categories]'))renderAllCategories();
 if(b.matches('[data-cancel-editor]'))editorClose();
 if(b.dataset.imageMove&&editor?.kind==='product'){const i=editor.images.findIndex(x=>x.id===b.dataset.imageMove),j=i+Number(b.dataset.direction);if(j>=0&&j<editor.images.length){[editor.images[i],editor.images[j]]=[editor.images[j],editor.images[i]];editor.dirty=true;renderEditorImages();}}
 if(b.dataset.imageRemove&&editor?.kind==='product'){editor.images=editor.images.filter(i=>i.id!==b.dataset.imageRemove);editor.dirty=true;renderEditorImages();}
 if(b.dataset.categoryOrder&&editor?.kind==='catalog'){const i=editor.selectedCategories.indexOf(b.dataset.categoryOrder),j=i+Number(b.dataset.direction);if(j>=0&&j<editor.selectedCategories.length){[editor.selectedCategories[i],editor.selectedCategories[j]]=[editor.selectedCategories[j],editor.selectedCategories[i]];editor.dirty=true;renderOrderedCategories();}}
 if(b.matches('[data-clear-category-image]')&&editor?.kind==='category'){editor.categoryBlob=null;editor.imagePath='';editor.dirty=true;$('#categoryImagePreview').src='assets/equipment-placeholder.svg';}
 if(b.matches('[data-test-service]'))await testService();
 if(b.matches('[data-enquiry-search],[data-enquiry-refresh]')){enquiriesFilter={status:$('#enquiryStatus').value,reference:$('#enquiryReference').value.trim()};enquiryPage=1;await renderEnquiries();}
 if(b.dataset.enquiryPage){enquiryPage=Number(b.dataset.enquiryPage);await renderEnquiries();}
 if(b.dataset.openEnquiry)enquiryEditor(enquiryRows.find(r=>r.id===b.dataset.openEnquiry));
 if(b.dataset.retryNotification)await retryNotification(b.dataset.retryNotification,b);
});
let searchTimer;
document.addEventListener('input',event=>{
 const target=event.target;
 if(target.id==='adminSearch'){clearTimeout(searchTimer);productFilters.q=target.value;productPage=1;searchTimer=setTimeout(renderProductRows,200);}
 if(target.closest('#editorContent')&&editor){editor.dirty=true;if(target.dataset.imageAlt){const im=editor.images.find(i=>i.id===target.dataset.imageAlt);if(im)im.alt_text=target.value;}}
 if(target.closest('#settingsForm'))settingsDirty=true;
 if(editor&&!editor.record&&target.name==='name'&&['catalog','category'].includes(editor.kind)){const slugInput=target.form.elements.slug;if(!slugInput.dataset.manual)slugInput.value=slugify(target.value);}
 if(target.name==='slug')target.dataset.manual='true';
});
document.addEventListener('change',async event=>{
 const n=event.target;
 const filters={adminCategory:'category',adminType:'type',adminPublication:'publication',adminReview:'review'};
 if(filters[n.id]){productFilters[filters[n.id]]=n.value;productPage=1;renderProductRows();}
 if(n.dataset.selectProduct){n.checked?selected.add(n.dataset.selectProduct):selected.delete(n.dataset.selectProduct);renderBulkBar();}
 if(n.id==='selectPage'){for(const p of filteredProducts().slice((productPage-1)*40,productPage*40))n.checked?selected.add(p.id):selected.delete(p.id);renderProductRows();}
 if(n.closest('#editorContent')&&editor)editor.dirty=true;
 if(n.name==='category')updatePlacements();
 if(['call_for_price','rental_call_for_price'].includes(n.name))updatePriceDisabled();
 if(n.id==='addProductImages')await addProductFiles(n);
 if(n.name==='catalog_category'&&editor?.kind==='catalog'){if(n.checked&&!editor.selectedCategories.includes(n.value))editor.selectedCategories.push(n.value);if(!n.checked)editor.selectedCategories=editor.selectedCategories.filter(id=>id!==n.value);renderOrderedCategories();}
 if(n.id==='categoryImageFile')await prepareCategoryImage(n);
 if(n.id==='heroImageFile')await prepareHero(n);
 if(n.closest('#settingsForm'))settingsDirty=true;
 if(n.id==='enquiryStatus'){enquiriesFilter.status=n.value;enquiryPage=1;await renderEnquiries();}
});
document.addEventListener('submit',async event=>{const form=event.target;if(['productEditor','catalogEditor','categoryEditor','enquiryEditor','settingsForm'].includes(form.id)){event.preventDefault();try{if(form.id==='productEditor')await saveProduct(form);if(form.id==='catalogEditor')await saveCatalog(form);if(form.id==='categoryEditor')await saveCategory(form);if(form.id==='enquiryEditor')await saveEnquiry(form);if(form.id==='settingsForm')await saveSettings(form);}catch(err){if(editor){busy(false);editorError(err.message);}else showMessage(err.message,'error');}}});
$('#closeEditor').addEventListener('click',()=>editorClose());
$('#editorDialog').addEventListener('cancel',event=>{event.preventDefault();editorClose();});
window.addEventListener('beforeunload',event=>{if(editor?.dirty||editor?.busy||settingsDirty){event.preventDefault();event.returnValue='';}});
$('#logoutButton').addEventListener('click',async()=>{if((editor?.dirty||settingsDirty)&&!confirm('Sign out and discard unsaved changes?'))return;if(editor?.busy)return;try{const c=await getClient();await c.auth.signOut();editor=null;settingsDirty=false;location.replace('admin-login.html');}catch(err){showMessage('Sign out could not be confirmed. '+err.message,'error');}});
(async()=>{
 try{
 profile=await checkStaff();if(!profile){location.replace('admin-login.html?reason=unauthorized');return;}
 const c=await getClient();c.auth.onAuthStateChange(event=>{if(event==='SIGNED_OUT'){editor=null;settingsDirty=false;location.replace('admin-login.html');}});
 await refreshData();$('#adminLoading').hidden=true;$('#adminApp').hidden=false;$('#adminIdentity').textContent='Signed in as billsadmin';
 if(LOCAL_PREVIEW){$('#adminBanner').hidden=false;$('#adminBanner').innerHTML=messageBox('Local preview is read-only. No catalog changes, image uploads or notification retries will be sent.','warning');}
 if(db.legacy){$('#adminBanner').hidden=false;$('#adminBanner').innerHTML=messageBox('Read-only compatibility mode: the new database tables are not installed. Your existing catalog remains intact. Review the included preflight and migration before enabling editing.','warning');}
 const params=new URLSearchParams(location.search);currentCatalog=params.get('catalog')||'';setTab(params.get('tab')||'products');
 }catch(err){$('#adminLoading').className='container';$('#adminLoading').innerHTML=`<div class="empty" style="margin-top:40px"><h1>Website manager could not load</h1><p>${e(err.message)}</p><a class="btn" href="admin-login.html">Return to login</a><button class="btn btn-primary" data-retry-admin>Retry</button></div>`;}
})();

document.addEventListener('click',event=>{if(event.target.closest('[data-retry-admin]'))location.reload();});

document.addEventListener('click',event=>{
 if(event.target.closest('[data-export-inventory]')&&db){
  const data={exported_at:new Date().toISOString(),format:'bills-inventory-v2',legacy:!!db.legacy,products:db.products,categories:db.categories,catalogs:db.catalogs};
  const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='bills-inventory-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);
 }
});
